/** Section id (the `#hash` target) paired with its label. Also drives the scroll-spy. */
private val NavItems = listOf(
    "home" to "Home",
    "docs" to "Documentation",
    "downloads" to "Downloads",
    "contact" to "Contact"
)

/** One easing for everything: quick start, long soft landing. */
private const val Ease = "cubic-bezier(0.22, 1, 0.36, 1)"

/** Height of the sticky bar (px). The scroll-spy offset + mobile dropdown use this. */
private const val BAR_HEIGHT = 72.0

/** Padding around the inner content of the bar. */
private const val BAR_PADDING_X = 28
private const val BAR_PADDING_X_COMPACT = 28

@Composable
fun NavBar() {
    var menuOpen by remember { mutableStateOf(false) }
    var scrolled by remember { mutableStateOf(false) }
    var progress by remember { mutableStateOf(0.0) }
    var activeSection by remember { mutableStateOf("home") }
    var hoveredLink by remember { mutableStateOf<String?>(null) }
    var brandHovered by remember { mutableStateOf(false) }
    var ctaHovered by remember { mutableStateOf(false) }
    var mounted by remember { mutableStateOf(false) }

    // Respect "reduce motion": every duration below goes through this
    val reduceMotion = remember { window.matchMedia("(prefers-reduced-motion: reduce)").matches }
    fun t(ms: Int) = if (reduceMotion) 0 else ms

    // Entrance: the bar glides down once the page is up
    LaunchedEffect(Unit) {
        delay(60)
        mounted = true
    }

    // Scroll state, reading progress, and the section currently in view.
    //
    // Contact fix: instead of only checking "which section's top is above the
    // threshold", we find the LAST section whose top is above the threshold
    // OR whose bottom is still below the threshold — so an in-view Contact
    // section always wins, even if the page can't scroll far enough to put
    // its top exactly at the top of the viewport. We also force Contact to
    // active when the user reaches the bottom of the page.
    DisposableEffect(Unit) {
        val update = {
            val y = window.scrollY
            scrolled = y > 8

            val max = (document.documentElement?.scrollHeight ?: 0) - window.innerHeight
            progress = if (max > 0) (y / max).coerceIn(0.0, 1.0) else 0.0

            // Threshold: just below the bar
            val threshold = BAR_HEIGHT + 8

            // If we're at (or near) the bottom of the page, force the last item
            // to be active — this is what makes Contact highlight reliably.
            if (max > 0 && y >= max - 4) {
                activeSection = NavItems.last().first
            } else {
                activeSection = NavItems
                    .map { it.first }
                    .lastOrNull { id ->
                        val el = document.getElementById(id) ?: return@lastOrNull false
                        val rect = el.getBoundingClientRect()
                        rect.top <= threshold && rect.bottom > threshold
                    }
                    ?: NavItems
                        .map { it.first }
                        .lastOrNull { id ->
                            (document.getElementById(id)?.getBoundingClientRect()?.top
                                ?: Double.MAX_VALUE) <= threshold
                        }
                            ?: "home"
            }
        }
        val onScroll: (Event) -> Unit = { update() }
        val onResize: (Event) -> Unit = { update() }
        window.addEventListener("scroll", onScroll)
        window.addEventListener("resize", onResize)
        update()
        onDispose {
            window.removeEventListener("scroll", onScroll)
            window.removeEventListener("resize", onResize)
        }
    }

    Column(
        Modifier
            .fillMaxWidth()
            .position(Position.Sticky)
            .top(0.px)
            .zIndex(50)
            .backgroundColor(GradeMateColors.Surface)
            .styleModifier {
                // Clear glass at top, frosted once scrolled
                property(
                    "background-color",
                    GradeMateColors.Surface.toRgba(alpha = if (scrolled) 0.86f else 0.62f)
                )
                val blur = if (scrolled) 20 else 10
                property("backdrop-filter", "saturate(180%) blur(${blur}px)")
                property("-webkit-backdrop-filter", "saturate(180%) blur(${blur}px)")

                // Subtle gradient sheen when compact
                property(
                    "background-image",
                    if (scrolled)
                        "linear-gradient(180deg, rgba(255,255,255,0.55), rgba(255,255,255,0) 100%)"
                    else "none"
                )

                property(
                    "border-bottom",
                    "1px solid ${if (scrolled) GradeMateColors.Border35 else "transparent"}"
                )
                property(
                    "box-shadow",
                    if (scrolled) "0 12px 40px -16px rgba(15, 23, 42, 0.14)"
                    else "0 0 0 rgba(15, 23, 42, 0)"
                )
                property("transform", if (mounted) "translateY(0)" else "translateY(-100%)")
                property("opacity", if (mounted) "1" else "0")
                property(
                    "transition",
                    "background-color ${t(350)}ms ease, " +
                            "backdrop-filter ${t(350)}ms ease, " +
                            "border-color ${t(350)}ms ease, " +
                            "box-shadow ${t(350)}ms ease, " +
                            "transform ${t(800)}ms $Ease, " +
                            "opacity ${t(500)}ms ease"
                )
            }
    ) {

        Box(
            Modifier
                .fillMaxWidth()
                .styleModifier { property("position", "relative") }
        ) {

            Row(
                Modifier
                    .fillMaxWidth()
                    .styleModifier {
                        // Consistent horizontal padding; slight vertical slimming on scroll
                        val padX = if (scrolled) BAR_PADDING_X_COMPACT else BAR_PADDING_X
                        val padY = if (scrolled) 10 else 14
                        property("padding", "${padY}px ${padX}px")
                        property("transition", "padding ${t(350)}ms $Ease")
                    },
                verticalAlignment = Alignment.CenterVertically,
                horizontalArrangement = Arrangement.SpaceBetween
            ) {

                // ---------------------------------------------------------
                // BRAND
                // ---------------------------------------------------------
                Row(
                    Modifier
                        .onClick { window.location.hash = "home" }
                        .onMouseEnter { brandHovered = true }
                        .onMouseLeave { brandHovered = false }
                        .styleModifier {
                            property("display", "inline-flex")
                            property("align-items", "center")
                            property("cursor", "pointer")
                            property("text-decoration", "none")
                            property("flex-shrink", "0")
                        }
                ) {
                    Box(
                        Modifier
                            .borderRadius(13.px)
                            .backgroundColor(GradeMateColors.Primary)
                            .styleModifier {
                                val side = if (scrolled) 38 else 42
                                property("width", "${side}px")
                                property("height", "${side}px")
                                property(
                                    "box-shadow",
                                    if (brandHovered) "0 14px 30px rgba(37, 99, 235, 0.38)"
                                    else "0 6px 18px rgba(37, 99, 235, 0.22)"
                                )
                                property(
                                    "transform",
                                    if (brandHovered) "rotate(-6deg) scale(1.08)" else "rotate(0deg) scale(1)"
                                )
                                property("overflow", "hidden")
                                property("flex-shrink", "0")
                                property(
                                    "transition",
                                    "width ${t(350)}ms $Ease, height ${t(350)}ms $Ease, " +
                                            "transform ${t(450)}ms cubic-bezier(0.34, 1.56, 0.64, 1), " +
                                            "box-shadow ${t(300)}ms ease"
                                )
                            }
                    ) {
                        Img(
                            src = "/grademate.png",
                            attrs = Modifier
                                .borderRadius(13.px)
                                .styleModifier {
                                    property("width", "100%")
                                    property("height", "100%")
                                    property("display", "block")
                                    property("object-fit", "cover")
                                }
                                .toAttrs()
                        )
                    }

                    Column(Modifier.margin(left = 12.px)) {
                        P(
                            Modifier
                                .margin(0.px)
                                .fontSize(18.px)
                                .fontWeight(FontWeight.Bold)
                                .color(GradeMateColors.Primary)
                                .styleModifier {
                                    property("letter-spacing", "-0.025em")
                                    property("line-height", "1.05")
                                    property("white-space", "nowrap")
                                }
                                .toAttrs()
                        ) {
                            Text("GradeMate")
                        }

                        P(
                            Modifier
                                .fontSize(9.px)
                                .fontWeight(FontWeight.Medium)
                                .color(GradeMateColors.TextSecondary)
                                .styleModifier {
                                    property("margin", "0")
                                    property("margin-top", if (scrolled) "0" else "4px")
                                    property("max-height", if (scrolled) "0" else "10px")
                                    property("opacity", if (scrolled) "0" else "1")
                                    property("overflow", "hidden")
                                    property("letter-spacing", "0.14em")
                                    property("line-height", "1")
                                    property("white-space", "nowrap")
                                    property(
                                        "transition",
                                        "max-height ${t(350)}ms $Ease, margin-top ${t(350)}ms $Ease, opacity ${t(250)}ms ease"
                                    )
                                }
                                .toAttrs()
                        ) {
                            Text("SMARTER GRADING")
                        }
                    }
                }

                // ---------------------------------------------------------
                // DESKTOP NAVIGATION
                // ---------------------------------------------------------
                Row(
                    DesktopNavLinksStyle.toModifier(),
                    verticalAlignment = Alignment.CenterVertically,
                    horizontalArrangement = Arrangement.spacedBy(10.px)
                ) {

                    NavItems.forEachIndexed { index, (id, label) ->
                        val isActive = activeSection == id
                        val isHovered = hoveredLink == id

                        Box(
                            Modifier
                                .onMouseEnter { hoveredLink = id }
                                .onMouseLeave { hoveredLink = null }
                                .styleModifier {
                                    property("position", "relative")
                                    property("opacity", if (mounted) "1" else "0")
                                    property("transform", if (mounted) "translateY(0)" else "translateY(-10px)")
                                    property(
                                        "transition",
                                        "opacity ${t(500)}ms ease ${t(250 + index * 80)}ms, " +
                                                "transform ${t(600)}ms $Ease ${t(250 + index * 80)}ms"
                                    )
                                }
                        ) {
                            Link(
                                "#$id",
                                label,
                                NavLinkStyle.toModifier()
                                    .thenIf(isActive) { Modifier.color(GradeMateColors.Primary) }
                            )

                            // Underline: sits below the text with clear breathing room
                            Box(
                                Modifier.styleModifier {
                                    property("position", "absolute")
                                    property("left", "14px")
                                    property("right", "14px")
                                    property("bottom", "-4px")
                                    property("height", "2px")
                                    property("border-radius", "2px")
                                    property("background-color", GradeMateColors.Primary.toString())
                                    property("pointer-events", "none")
                                    property("transform-origin", "center")
                                    property(
                                        "transform",
                                        when {
                                            isActive -> "scaleX(1)"
                                            isHovered -> "scaleX(0.45)"
                                            else -> "scaleX(0)"
                                        }
                                    )
                                    property("opacity", if (isActive) "1" else if (isHovered) "0.55" else "0")
                                    property(
                                        "transition",
                                        "transform ${t(350)}ms $Ease, opacity ${t(250)}ms ease"
                                    )
                                }
                            )
                        }
                    }

                    // CTA
                    Box(
                        Modifier
                            .margin(left = 10.px)
                            .styleModifier {
                                property("opacity", if (mounted) "1" else "0")
                                property("transform", if (mounted) "translateY(0)" else "translateY(-10px)")
                                property(
                                    "transition",
                                    "opacity ${t(500)}ms ease ${t(250 + NavItems.size * 80)}ms, " +
                                            "transform ${t(600)}ms $Ease ${t(250 + NavItems.size * 80)}ms"
                                )
                            }
                    ) {
                        Link(
                            path = "#downloads",
                            text = "Get GradeMate",
                            modifier = PrimaryButtonStyle
                                .toModifier()
                                .onMouseEnter { ctaHovered = true }
                                .onMouseLeave { ctaHovered = false }
                                .styleModifier {
                                    property("display", "inline-flex")
                                    property("align-items", "center")
                                    property("justify-content", "center")
                                    property("height", "42px")
                                    property("box-sizing", "border-box")
                                    property("padding", "0 20px")
                                    property("border-radius", "10px")
                                    property("text-decoration", "none")
                                    property("font-size", "14px")
                                    property("font-weight", "600")
                                    property("line-height", "1")
                                    property("color", Colors.White.toString())
                                    property(
                                        "background-image",
                                        "linear-gradient(135deg, rgba(255, 255, 255, 0.22), rgba(255, 255, 255, 0) 60%)"
                                    )
                                    property(
                                        "transform",
                                        if (ctaHovered) "translateY(-2px)" else "translateY(0)"
                                    )
                                    property(
                                        "box-shadow",
                                        if (ctaHovered) "0 16px 34px -8px rgba(37, 99, 235, 0.45)"
                                        else "0 6px 16px rgba(37, 99, 235, 0.22)"
                                    )
                                    property(
                                        "transition",
                                        "transform ${t(250)}ms $Ease, box-shadow ${t(250)}ms ease, background-color 150ms ease"
                                    )
                                }
                        )
                    }
                }

                // ---------------------------------------------------------
                // MOBILE MENU BUTTON
                // ---------------------------------------------------------
                Button(
                    attrs = Modifier
                        .size(42.px)
                        .borderRadius(12.px)
                        .onClick { menuOpen = !menuOpen }
                        .styleModifier {
                            property("position", "relative")
                            property("padding", "0")
                            property(
                                "background-color",
                                if (menuOpen) GradeMateColors.Primary.toString()
                                else GradeMateColors.Surface.toString()
                            )
                            property("border", "1px solid ${GradeMateColors.Border35}")
                            property("cursor", "pointer")
                            property("flex-shrink", "0")
                            property(
                                "transition",
                                "background-color ${t(250)}ms ease, border-color ${t(250)}ms ease"
                            )
                        }
                        .toAttrs {
                            attr("type", "button")
                            attr("aria-label", if (menuOpen) "Close menu" else "Open menu")
                            attr("aria-expanded", menuOpen.toString())
                        }
                ) {
                    listOf(-6, 0, 6).forEachIndexed { index, offset ->
                        Span(
                            attrs = Modifier
                                .width(19.px)
                                .height(2.px)
                                .borderRadius(2.px)
                                .styleModifier {
                                    property("position", "absolute")
                                    property("top", "50%")
                                    property("left", "50%")
                                    property(
                                        "background-color",
                                        if (menuOpen) Colors.White.toString()
                                        else GradeMateColors.TextPrimary.toString()
                                    )
                                    property(
                                        "transform",
                                        when {
                                            !menuOpen -> "translate(-50%, calc(-50% + ${offset}px))"
                                            index == 0 -> "translate(-50%, -50%) rotate(45deg)"
                                            index == 2 -> "translate(-50%, -50%) rotate(-45deg)"
                                            else -> "translate(-50%, -50%) scaleX(0)"
                                        }
                                    )
                                    property("opacity", if (menuOpen && index == 1) "0" else "1")
                                    property(
                                        "transition",
                                        "transform ${t(350)}ms $Ease, opacity ${t(200)}ms ease, background-color ${t(250)}ms ease"
                                    )
                                }
                                .toAttrs()
                        )
                    }
                }
            }

            // Reading progress hairline
            Box(
                Modifier
                    .fillMaxWidth()
                    .styleModifier {
                        property("position", "absolute")
                        property("left", "0")
                        property("bottom", "-1px")
                        property("height", "2px")
                        property("pointer-events", "none")
                        property(
                            "background-image",
                            "linear-gradient(90deg, ${GradeMateColors.Primary}, ${GradeMateColors.Primary.toRgba(alpha = 0.35f)})"
                        )
                        property("transform-origin", "left")
                        property("transform", "scaleX($progress)")
                        property("opacity", if (scrolled) "1" else "0")
                        property("transition", "opacity ${t(300)}ms ease")
                    }
            )
        }

        // -------------------------------------------------------------
        // MOBILE DROPDOWN
        // -------------------------------------------------------------
        Column(
            Modifier
                .fillMaxWidth()
                .styleModifier {
                    property("overflow-x", "hidden")
                    property("overflow-y", if (menuOpen) "auto" else "hidden")
                    property("max-height", if (menuOpen) "calc(100vh - ${BAR_HEIGHT.toInt()}px)" else "0")
                    property("opacity", if (menuOpen) "1" else "0")
                    property("visibility", if (menuOpen) "visible" else "hidden")
                    property(
                        "border-top",
                        if (menuOpen) "1px solid ${GradeMateColors.Border35}" else "0 solid transparent"
                    )
                    property(
                        "box-shadow",
                        if (menuOpen) "0 20px 40px -16px rgba(15, 23, 42, 0.18)" else "none"
                    )
                    property(
                        "transition",
                        "max-height ${t(450)}ms $Ease, opacity ${t(300)}ms ease, " +
                                "visibility 0s linear ${if (menuOpen) 0 else t(450)}ms"
                    )
                }
        ) {
            Column(
                Modifier
                    .fillMaxWidth()
                    .padding(leftRight = 24.px, topBottom = 20.px),
                verticalArrangement = Arrangement.spacedBy(6.px)
            ) {

                NavItems.forEachIndexed { index, (id, label) ->
                    val isActive = activeSection == id
                    val delay = if (menuOpen) t(90 + index * 55) else 0

                    Link(
                        "#$id",
                        label,
                        NavLinkStyle
                            .toModifier()
                            .fillMaxWidth()
                            .padding(topBottom = 12.px, leftRight = 14.px)
                            .borderRadius(10.px)
                            .onClick { menuOpen = false }
                            .styleModifier {
                                property("opacity", if (menuOpen) "1" else "0")
                                property("transform", if (menuOpen) "translateY(0)" else "translateY(-10px)")
                                if (isActive) {
                                    property("background-color", GradeMateColors.Primary.toRgba(alpha = 0.08f))
                                    property("color", GradeMateColors.Primary.toString())
                                }
                                property(
                                    "transition",
                                    "opacity ${t(300)}ms ease ${delay}ms, " +
                                            "transform ${t(450)}ms $Ease ${delay}ms, " +
                                            "background-color 200ms ease"
                                )
                            }
                    )
                }

                val ctaDelay = if (menuOpen) t(90 + NavItems.size * 55) else 0
                Link(
                    path = "#downloads",
                    text = "Get GradeMate",
                    modifier = PrimaryButtonStyle
                        .toModifier()
                        .fillMaxWidth()
                        .margin(top = 8.px)
                        .padding(topBottom = 12.px, leftRight = 16.px)
                        .borderRadius(10.px)
                        .fontSize(14.px)
                        .fontWeight(FontWeight.SemiBold)
                        .color(Colors.White)
                        .onClick { menuOpen = false }
                        .styleModifier {
                            property("display", "inline-flex")
                            property("align-items", "center")
                            property("justify-content", "center")
                            property("text-decoration", "none")
                            property(
                                "background-image",
                                "linear-gradient(135deg, rgba(255, 255, 255, 0.2), rgba(255, 255, 255, 0) 60%)"
                            )
                            property("opacity", if (menuOpen) "1" else "0")
                            property("transform", if (menuOpen) "translateY(0)" else "translateY(-10px)")
                            property(
                                "transition",
                                "opacity ${t(300)}ms ease ${ctaDelay}ms, transform ${t(450)}ms $Ease ${ctaDelay}ms"
                            )
                        }
                )
            }
        }
    }
}