/** Same easing as the nav bar, hero and docs: quick start, long soft landing. */
private const val Ease = "cubic-bezier(0.22, 1, 0.36, 1)"

private fun prefersReducedMotion() = window.matchMedia("(prefers-reduced-motion: reduce)").matches

/** Best guess at the visitor's platform, using the same names as the download options. */
private fun detectPlatform(): String? {
    val ua = window.navigator.userAgent.lowercase()
    return when {
        "android" in ua -> "Android"          // checked before Linux: Android reports both
        "iphone" in ua || "ipad" in ua -> "iOS"
        "windows" in ua -> "Windows"
        "mac os" in ua || "macintosh" in ua -> "macOS"
        "linux" in ua || "x11" in ua -> "Linux"
        else -> null
    }
}

/**
 * Fades and lifts its content in the first time it scrolls into view.
 * [id] must be unique on the page; it's how the block is found on scroll.
 */
@Composable
private fun Reveal(
    id: String,
    modifier: Modifier = Modifier,
    delayMs: Int = 0,
    content: @Composable () -> Unit
) {
    var visible by remember { mutableStateOf(false) }
    val reduce = remember { prefersReducedMotion() }

    DisposableEffect(Unit) {
        val check = {
            val top = document.getElementById(id)?.getBoundingClientRect()?.top
            if (reduce || (top != null && top < window.innerHeight * 0.9)) visible = true
        }
        val onScroll: (Event) -> Unit = { check() }
        window.addEventListener("scroll", onScroll)
        check()
        onDispose { window.removeEventListener("scroll", onScroll) }
    }

    Box(
        modifier
            .id(id)
            .fillMaxWidth()
            .styleModifier {
                val d = if (reduce) 0 else delayMs
                val dur = if (reduce) 0 else 800
                property("opacity", if (visible) "1" else "0")
                property("transform", if (visible) "translateY(0)" else "translateY(28px)")
                property("transition", "opacity ${dur}ms ease ${d}ms, transform ${dur}ms $Ease ${d}ms")
            }
    ) {
        content()
    }
}

// Hover lift for a download card
val DownloadCardStyle = CssStyle {
    base {
        Modifier
            .fillMaxWidth()
            .padding(28.px)
            .styleModifier {
                property("height", "100%")
                property("box-sizing", "border-box")
                property("transition", "transform 0.2s ease, box-shadow 0.2s ease")
            }
    }
    hover {
        Modifier.styleModifier {
            property("transform", "translateY(-4px)")
            property("box-shadow", "0 16px 32px rgba(0, 0, 0, 0.10)")
        }
    }
}

@Composable
fun DownloadsSection() {
    // ---------- Firestore state ----------
    var downloads by remember { mutableStateOf<List<DownloadOption>>(emptyList()) }
    var isLoading by remember { mutableStateOf(true) }
    var errorMessage by remember { mutableStateOf("") }
    var reloadKey by remember { mutableStateOf(0) }
    val recommended = remember { detectPlatform() }

    LaunchedEffect(reloadKey) {
        isLoading = true
        errorMessage = ""
        try {
            downloads = fetchDownloads()
        } catch (e: Throwable) {
            errorMessage = "Couldn't load downloads: ${e.message}"
        } finally {
            isLoading = false
        }
    }

    Box(
        SectionStyle
            .toModifier()
            .id("downloads")
    ) {
        Column(
            SectionInnerStyle.toModifier()
        ) {

            // Section heading
            Reveal("downloads-header") {
                Column(Modifier.fillMaxWidth()) {
                    P(
                        EyebrowStyle
                            .toModifier()
                            .margin(0.px)
                            .styleModifier {
                                property("letter-spacing", "0.14em")
                                property("text-transform", "uppercase")
                                property("font-weight", "600")
                            }
                            .toAttrs()
                    ) {
                        Text("Downloads")
                    }

                    P(
                        SectionHeadingStyle
                            .toModifier()
                            .margin(top = 10.px, bottom = 12.px)
                            .styleModifier {
                                property("font-size", "clamp(30px, 4.2vw, 46px)")
                                property("letter-spacing", "-0.035em")
                                property("line-height", "1.08")
                            }
                            .toAttrs()
                    ) {
                        Text("Choose your platform")
                    }

                    P(
                        SectionSubtitleStyle
                            .toModifier()
                            .margin(0.px)
                            .styleModifier {
                                property("max-width", "620px")
                                property("line-height", "1.7")
                            }
                            .toAttrs()
                    ) {
                        Text(
                            "Download the latest version of GradeMate for your device. " +
                                    "All builds are free to use."
                        )
                    }
                }
            }

            // ---------- Loading ----------
            if (isLoading) {
                DownloadsSkeleton()
                return@Column
            }

            // ---------- Error ----------
            if (errorMessage.isNotEmpty()) {
                Div(
                    attrs = Modifier
                        .margin(top = 40.px)
                        .styleModifier {
                            property("padding", "22px 26px")
                            property("border-radius", "16px")
                            property("background-color", "rgba(220, 38, 38, 0.06)")
                            property("border", "1px solid rgba(220, 38, 38, 0.22)")
                        }
                        .toAttrs { attr("role", "alert") }
                ) {
                    P(
                        Modifier
                            .margin(0.px)
                            .fontSize(15.px)
                            .lineHeight(1.6)
                            .color(GradeMateColors.TextPrimary)
                            .styleModifier { property("color", "rgb(185, 28, 28)") }
                            .toAttrs()
                    ) {
                        Text(errorMessage)
                    }

                    Button(
                        attrs = Modifier
                            .margin(top = 14.px)
                            .onClick { reloadKey++ }
                            .styleModifier {
                                property("padding", "10px 20px")
                                property("border-radius", "10px")
                                property("border", "1px solid rgba(220, 38, 38, 0.35)")
                                property("background-color", "#ffffff")
                                property("color", "rgb(185, 28, 28)")
                                property("font-family", "inherit")
                                property("font-size", "14px")
                                property("font-weight", "600")
                                property("cursor", "pointer")
                            }
                            .toAttrs { attr("type", "button") }
                    ) {
                        Text("Try again")
                    }
                }
                return@Column
            }

            // ---------- Empty ----------
            if (downloads.isEmpty()) {
                Div(
                    attrs = Modifier
                        .margin(top = 40.px)
                        .styleModifier {
                            property("padding", "40px 24px")
                            property("text-align", "center")
                            property("border-radius", "16px")
                            property("border", "1px dashed ${GradeMateColors.Primary.toRgba(alpha = 0.3f)}")
                            property("background-color", GradeMateColors.Primary.toRgba(alpha = 0.03f))
                        }
                        .toAttrs()
                ) {
                    P(
                        Modifier
                            .margin(0.px)
                            .fontSize(15.px)
                            .color(GradeMateColors.TextSecondary)
                            .toAttrs()
                    ) {
                        Text("No downloads available at the moment.")
                    }
                }
                return@Column
            }

            // ---------- Download cards ----------
            Div(
                attrs = DownloadsGridStyle
                    .toModifier()
                    .margin(top = 44.px)
                    .styleModifier {
                        property("align-items", "stretch")
                    }
                    .toAttrs()
            ) {
                downloads.forEachIndexed { index, option ->
                    DownloadCard(
                        option = option,
                        index = index,
                        isRecommended = option.platform == recommended
                    )
                }
            }
        }
    }
}

// ---------------------------------------------------------------------------
// One download card
// ---------------------------------------------------------------------------
@Composable
private fun DownloadCard(
    option: DownloadOption,
    index: Int,
    isRecommended: Boolean
) {
    var hovered by remember { mutableStateOf(false) }
    val reduce = remember { prefersReducedMotion() }
    fun t(ms: Int) = if (reduce) 0 else ms

    val iconName = when (option.platform) {
        "Android" -> "android"
        "Windows" -> "windows"
        "Linux" -> "linux"
        "macOS" -> "apple"
        "iOS" -> "apple"
        else -> "download"
    }

    // Cards rise in one after another as they scroll into view
    Reveal(
        id = "download-card-$index",
        modifier = Modifier.styleModifier { property("height", "100%") },
        delayMs = index * 110
    ) {
        Column(
            CardStyle
                .toModifier()
                .then(DownloadCardStyle.toModifier())
                .onMouseEnter { hovered = true }
                .onMouseLeave { hovered = false }
                .styleModifier {
                    property("position", "relative")
                    property("border-top", "3px solid ${option.accent.toRgba()}")
                    // A faint wash of the platform's colour from the top-left corner
                    property(
                        "background-image",
                        "radial-gradient(120% 55% at 0% 0%, ${option.accent.toRgba(alpha = 0.08f)}, transparent 65%)"
                    )
                    property("transform", if (hovered) "translateY(-6px)" else "translateY(0)")
                    property(
                        "box-shadow",
                        if (hovered) "0 26px 50px -22px ${option.accent.toRgba(alpha = 0.5f)}"
                        else "0 10px 28px -18px rgba(15, 23, 42, 0.18)"
                    )
                    property(
                        "transition",
                        "transform ${t(320)}ms $Ease, box-shadow ${t(320)}ms ease"
                    )
                }
        ) {

            // "Recommended" tag on the card that matches the visitor's device
            if (isRecommended) {
                Span(
                    attrs = Modifier
                        .styleModifier {
                            property("position", "absolute")
                            property("top", "14px")
                            property("right", "14px")
                            property("padding", "4px 11px")
                            property("border-radius", "999px")
                            property("background-color", option.accent.toRgba())
                            property("color", "#ffffff")
                            property("font-size", "11px")
                            property("font-weight", "700")
                            property("letter-spacing", "0.04em")
                        }
                        .toAttrs()
                ) {
                    Text("Recommended for you")
                }
            }

            // Platform icon: tilts and grows a little when the card is hovered
            Box(
                Modifier
                    .size(52.px)
                    .borderRadius(14.px)
                    .styleModifier {
                        property("background-color", option.accent.toRgba(alpha = 0.14f))
                        property("display", "flex")
                        property("align-items", "center")
                        property("justify-content", "center")
                        property(
                            "transform",
                            if (hovered) "rotate(-6deg) scale(1.1)" else "rotate(0deg) scale(1)"
                        )
                        property(
                            "transition",
                            "transform ${t(450)}ms cubic-bezier(0.34, 1.56, 0.64, 1)"
                        )
                    }
            ) {
                FaIcon(
                    name = iconName,
                    style = IconCategory.BRAND,
                    modifier = Modifier
                        .fontSize(25.px)
                        .color(option.accent)
                )
            }

            // Platform name
            P(
                Modifier
                    .margin(top = 20.px, bottom = 0.px)
                    .fontSize(21.px)
                    .fontWeight(FontWeight.Bold)
                    .color(GradeMateColors.TextPrimary)
                    .styleModifier { property("letter-spacing", "-0.02em") }
                    .toAttrs()
            ) {
                Text(option.platform)
            }

            // Version and size as two small chips
            Div(
                attrs = Modifier
                    .margin(top = 10.px)
                    .styleModifier {
                        property("display", "flex")
                        property("flex-wrap", "wrap")
                        property("align-items", "center")
                        property("gap", "8px")
                    }
                    .toAttrs()
            ) {
                Span(
                    attrs = Modifier
                        .styleModifier {
                            property("padding", "4px 10px")
                            property("border-radius", "999px")
                            property("background-color", option.accent.toRgba(alpha = 0.12f))
                            property("color", option.accent.toRgba())
                            property("font-size", "12px")
                            property("font-weight", "600")
                            property("font-variant-numeric", "tabular-nums")
                        }
                        .toAttrs()
                ) {
                    Text(option.version)
                }
                Span(
                    attrs = Modifier
                        .styleModifier {
                            property("padding", "4px 10px")
                            property("border-radius", "999px")
                            property("background-color", GradeMateColors.TextSecondary.toRgba(alpha = 0.1f))
                            property("color", "${GradeMateColors.TextSecondary}")
                            property("font-size", "12px")
                            property("font-weight", "600")
                            property("font-variant-numeric", "tabular-nums")
                        }
                        .toAttrs()
                ) {
                    Text(option.size)
                }
            }

            // Description
            P(
                Modifier
                    .margin(top = 16.px, bottom = 0.px)
                    .fontSize(14.px)
                    .lineHeight(1.7)
                    .color(GradeMateColors.TextSecondary)
                    .styleModifier {
                        property("overflow-wrap", "break-word")
                        // Pushes the button to the bottom so all buttons line up across cards
                        property("flex-grow", "1")
                    }
                    .toAttrs()
            ) {
                Text(option.description)
            }

            // Download button: one anchor styled as a button, no <a> nested in a <button>
            Link(
                option.href,
                modifier = Modifier
                    .margin(top = 26.px)
                    .styleModifier {
                        property("display", "flex")
                        property("align-items", "center")
                        property("justify-content", "center")
                        property("gap", "10px")
                        property("width", "100%")
                        property("box-sizing", "border-box")
                        property("height", "50px")
                        property("border-radius", "12px")
                        property("text-decoration", "none")
                        property("color", "#ffffff")
                        property("font-size", "15px")
                        property("font-weight", "600")
                        property("line-height", "1")
                        property("background-color", option.accent.toRgba())
                        // Soft sheen over the platform colour
                        property(
                            "background-image",
                            "linear-gradient(135deg, rgba(255, 255, 255, 0.2), rgba(255, 255, 255, 0) 60%)"
                        )
                        property(
                            "box-shadow",
                            if (hovered) "0 16px 30px -10px ${option.accent.toRgba(alpha = 0.6f)}"
                            else "0 8px 18px -8px ${option.accent.toRgba(alpha = 0.5f)}"
                        )
                        property("transition", "box-shadow ${t(320)}ms ease")
                    }
            ) {
                FaIcon(
                    name = "download",
                    style = IconCategory.SOLID,
                    modifier = Modifier.fontSize(14.px)
                )
                Text("Download")
                // Arrow slides forward while the card is hovered
                Span(
                    attrs = Modifier
                        .styleModifier {
                            property("display", "inline-block")
                            property("transform", if (hovered) "translateX(4px)" else "translateX(0)")
                            property("transition", "transform ${t(300)}ms $Ease")
                        }
                        .toAttrs()
                ) {
                    Text("→")
                }
            }
        }
    }
}

// ---------------------------------------------------------------------------
// Loading skeleton: same grid and card surface as the real cards
// ---------------------------------------------------------------------------
@Composable
private fun DownloadsSkeleton() {
    var dim by remember { mutableStateOf(false) }
    val reduce = remember { prefersReducedMotion() }

    // One slow breathing pulse for the whole grid
    LaunchedEffect(Unit) {
        if (!reduce) {
            while (true) {
                delay(900)
                dim = !dim
            }
        }
    }

    val block = GradeMateColors.Primary.toRgba(alpha = 0.10f)

    Div(
        attrs = DownloadsGridStyle
            .toModifier()
            .margin(top = 44.px)
            .styleModifier {
                property("align-items", "stretch")
                property("opacity", if (dim) "0.5" else "1")
                property("transition", "opacity 900ms ease-in-out")
            }
            .toAttrs {
                attr("role", "status")
                attr("aria-label", "Loading downloads")
            }
    ) {
        repeat(3) {
            Column(
                CardStyle
                    .toModifier()
                    .padding(28.px)
                    .fillMaxWidth()
            ) {
                Div(
                    attrs = Modifier.styleModifier {
                        property("width", "52px")
                        property("height", "52px")
                        property("border-radius", "14px")
                        property("background-color", block)
                    }.toAttrs()
                )
                Div(
                    attrs = Modifier.styleModifier {
                        property("width", "45%")
                        property("height", "20px")
                        property("margin-top", "20px")
                        property("border-radius", "6px")
                        property("background-color", block)
                    }.toAttrs()
                )
                Div(
                    attrs = Modifier.styleModifier {
                        property("display", "flex")
                        property("gap", "8px")
                        property("margin-top", "12px")
                    }.toAttrs()
                ) {
                    listOf(22, 18).forEach { w ->
                        Div(
                            attrs = Modifier.styleModifier {
                                property("width", "${w}%")
                                property("height", "22px")
                                property("border-radius", "999px")
                                property("background-color", block)
                            }.toAttrs()
                        )
                    }
                }
                Div(
                    attrs = Modifier.styleModifier {
                        property("width", "100%")
                        property("height", "12px")
                        property("margin-top", "18px")
                        property("border-radius", "6px")
                        property("background-color", block)
                    }.toAttrs()
                )
                Div(
                    attrs = Modifier.styleModifier {
                        property("width", "75%")
                        property("height", "12px")
                        property("margin-top", "8px")
                        property("border-radius", "6px")
                        property("background-color", block)
                    }.toAttrs()
                )
                Div(
                    attrs = Modifier.styleModifier {
                        property("width", "100%")
                        property("height", "50px")
                        property("margin-top", "26px")
                        property("border-radius", "12px")
                        property("background-color", block)
                    }.toAttrs()
                )
            }
        }
    }
}