                            Modifier
                                .margin(top = 22.px)
                                .styleModifier {
                                    property("padding", "14px 18px")
                                    property("border-radius", "12px")
                                    property("background-color", GradeMateColors.Primary.toRgba(alpha = 0.06f))
                                    property("border-left", "3px solid ${GradeMateColors.Primary.toRgba(alpha = 0.55f)}")
                                }
                        ) {
                            P(
                                Modifier
                                    .margin(0.px)
                                    .fontSize(14.px)
                                    .lineHeight(1.7)
                                    .color(GradeMateColors.TextSecondary)
