                                property("background-color", "${GradeMateColors.Background}")
                                property("border", "1px solid ${GradeMateColors.Border}")
                                property("max-width", "100%")
                                property("overflow-x", "auto")
                                property("align-self", "flex-start")
                            }
                            .toAttrs()
                    ) {
                        // The highlight glides between segments
                        Div(
                            attrs = Modifier.styleModifier {
                                property("position", "absolute")
                                property("top", "4px")
                                property("bottom", "4px")
                                property("left", "4px")
