                                        )
                                    }
                            ) {
                                P(
                                    Modifier
                                        .margin(0.px)
                                        .fontSize(17.px)
                                        .fontWeight(FontWeight.SemiBold)
                                        .color(GradeMateColors.TextPrimary)
                                        .styleModifier { property("letter-spacing", "-0.01em") }
                                        .toAttrs()
                                ) {
                                    Text("${selectedPlatform.label} requirements")
                                }

                                requirementRow(
                                    "Operating system",
                                    selectedPlatform.minOs
                                )

                                requirementRow(
                                    "Storage",
                                    selectedPlatform.storage
                                )

                                requirementRow(
                                    "Other",
                                    selectedPlatform.extra
                                )
                            }
                        }
                    }
