                        P(
                            Modifier
                                .margin(0.px)
                                .fontWeight(FontWeight.Bold)
                                .color(Colors.White)
                                .styleModifier {
                                    property("font-size", "clamp(22px, 3vw, 30px)")
                                    property("letter-spacing", "-0.025em")
                                    property("text-align", "center")
