/**
 * JS's built-in encodeURIComponent. Needed so the subject/body survive as valid
 * URL query params — spaces, newlines, and punctuation in a raw mailto: link
 * would either get silently dropped or break the URL.
 */
private fun encodeURIComponent(str: String): String =
    js("encodeURIComponent(str)") as String

/**
 * Fades and lifts its content in the first time it scrolls into view.
 * [id] must be unique on the page; it's how the block is found on scroll.
 */
@Composable
private fun Reveal(
    id: String,
    modifier: Modifier = Modifier,
    delayMs: Int = 0,
    content: @Composable () -> Unit
) {
    var visible by remember { mutableStateOf(false) }
    val reduce = remember { prefersReducedMotion() }

    DisposableEffect(Unit) {
        val check = {
            val top = document.getElementById(id)?.getBoundingClientRect()?.top
            if (reduce || (top != null && top < window.innerHeight * 0.9)) visible = true
        }
        val onScroll: (Event) -> Unit = { check() }
        window.addEventListener("scroll", onScroll)
        check()
        onDispose { window.removeEventListener("scroll", onScroll) }
    }

    Box(
        modifier
            .id(id)
            .fillMaxWidth()
            .styleModifier {
                val d = if (reduce) 0 else delayMs
                val dur = if (reduce) 0 else 800
                property("opacity", if (visible) "1" else "0")
                property("transform", if (visible) "translateY(0)" else "translateY(28px)")
                property("transition", "opacity ${dur}ms ease ${d}ms, transform ${dur}ms $Ease ${d}ms")
            }
    ) {
        content()
    }
}

// Shared style for the two inputs + the textarea. Modern treatment:
//  - larger radius, softer default border
//  - hover darkens border slightly (affordance)
//  - focus swaps border to Primary + adds a soft outer glow
//  - smooth cubic-bezier transition instead of linear ease
//  - placeholder + caret colored to match the design system
val ContactFieldStyle = CssStyle {
    base {
        Modifier
            .fillMaxWidth()
            .fontSize(15.px)
            .color(GradeMateColors.TextPrimary)
            .styleModifier {
                property("border", "1px solid ${GradeMateColors.Border.toRgba()}")
                property("border-radius", "12px")
                property("padding", "13px 16px")
                property("outline", "none")
                property("font-family", "inherit")
                property("box-sizing", "border-box")
                property("background-color", GradeMateColors.Surface.toRgba())
                property("transition", "border-color 180ms cubic-bezier(0.4, 0, 0.2, 1), box-shadow 180ms cubic-bezier(0.4, 0, 0.2, 1), background-color 180ms cubic-bezier(0.4, 0, 0.2, 1)")
                property("caret-color", GradeMateColors.Primary.toRgba())
                // Placeholder styling (browser pseudo-element).
                property("--placeholder-color", GradeMateColors.TextSecondary.toRgba(alpha = 0.55f))
            }
    }
    hover {
        Modifier.styleModifier {
            property("border-color", GradeMateColors.Primary.toRgba(alpha = 0.45f))
        }
    }
    focusVisible {
        Modifier.styleModifier {
            property("border-color", GradeMateColors.Primary.toRgba())
            property("box-shadow", "0 0 0 4px ${GradeMateColors.Primary.toRgba(alpha = 0.14f)}")
        }
    }
}

@Composable
fun ContactSection() {
    var name by remember { mutableStateOf("") }
    var email by remember { mutableStateOf("") }
    var message by remember { mutableStateOf("") }
    var statusMessage by remember { mutableStateOf<String?>(null) }
    var statusIsError by remember { mutableStateOf(false) }
    var sendHovered by remember { mutableStateOf(false) }
    val reduce = remember { prefersReducedMotion() }
    fun t(ms: Int) = if (reduce) 0 else ms

    Box(
        SectionStyle
            .toModifier()
            .id("contact")
            .backgroundColor(GradeMateColors.Surface)
            .styleModifier {
                // A soft pool of brand colour behind the form
                property(
                    "background-image",
                    "radial-gradient(50% 60% at 90% 80%, ${GradeMateColors.Primary.toRgba(alpha = 0.06f)}, transparent 70%)"
                )
            }
    ) {
        Div(
            attrs = ResponsiveRowStyle
                .toModifier()
                .then(SectionInnerStyle.toModifier())
                .styleModifier {
                    property("gap", "clamp(32px, 6vw, 80px)")
                    property("align-items", "center")
                }
                .toAttrs()
        ) {
            Reveal("contact-intro") {
                Column(Modifier.fillMaxWidth()) {

                    P(
                        EyebrowStyle
                            .toModifier()
                            .margin(0.px)
                            .styleModifier {
                                property("letter-spacing", "0.14em")
                                property("text-transform", "uppercase")
                                property("font-weight", "600")
                            }
                            .toAttrs()
                    ) {
                        Text("Contact us")
                    }

                    P(
                        SectionHeadingStyle
                            .toModifier()
                            .margin(top = 12.px, bottom = 14.px)
                            .styleModifier {
                                property("font-size", "clamp(30px, 4.2vw, 46px)")
                                property("letter-spacing", "-0.035em")
                                property("line-height", "1.08")
                            }
                            .toAttrs()
                    ) {
                        Text("Questions or feedback?")
                    }

                    P(
                        SectionSubtitleStyle
                            .toModifier()
                            .margin(0.px)
                            .styleModifier { property("line-height", "1.7") }
                            .toAttrs()
                    ) {
                        Text("Send a message and we'll get back to you, or reach out directly.")
                    }

                    Column(
                        Modifier
                            .margin(top = 32.px)
                            .gap(14.px)
                    ) {
                        ContactLink(
                            href = "mailto:lennycodes2000@gmail.com",
                            iconName = "envelope",
                            iconCategory = IconCategory.SOLID,
                            label = "lennycodes2000@gmail.com"
                        )

                        ContactLink(
                            href = "https://wa.me/255686777093",
                            iconName = "whatsapp",
                            iconCategory = IconCategory.BRAND,
                            label = "WhatsApp: +255 686 777 093"
                        )
                    }
                }
            }

            Reveal("contact-form", delayMs = 150) {
                Column(
                    CardStyle
                        .toModifier()
                        .fillMaxWidth()
                        .gap(18.px)
                        .styleModifier {
                            property("padding", "clamp(22px, 3.5vw, 32px)")
                            property("box-shadow", "0 30px 60px -36px rgba(15, 23, 42, 0.28)")
                        }
                ) {
                    contactField("Name", "contact-name") {
                        Input(
                            type = InputType.Text,
                            attrs = ContactFieldStyle.toModifier().toAttrs {
                                attr("id", "contact-name")
                                placeholder("Loveness Florence")
                                name("name")
                                value(name)
                                onInput { event -> name = event.value }
                            }
                        )
                    }
                    contactField("Email", "contact-email") {
                        Input(
                            type = InputType.Email,
                            attrs = ContactFieldStyle.toModifier().toAttrs {
                                attr("id", "contact-email")
                                placeholder("loveness@example.com")
                                name("email")
                                value(email)
                                onInput { event -> email = event.value }
                            }
                        )
                    }
                    contactField("Message", "contact-message") {
                        TextArea(
                            attrs = ContactFieldStyle
                                .toModifier()
                                .height(130.px)
                                .styleModifier { property("resize", "vertical") }
                                .toAttrs {
                                    attr("id", "contact-message")
                                    placeholder("How can we help?")
                                    name("message")
                                    value(message)
                                    onInput { event -> message = event.value }
                                }
                        )
                    }

                    // Checks the basics, then opens the visitor's email app with everything filled in
                    Button(
                        onClick = {
                            val emailLooksValid = email.contains("@") && email.contains(".")
                            when {
                                name.isBlank() || message.isBlank() -> {
                                    statusIsError = true
                                    statusMessage = "Please add your name and a message."
                                }
                                !emailLooksValid -> {
                                    statusIsError = true
                                    statusMessage = "Please enter a valid email address."
                                }
                                else -> {
                                    val subject = encodeURIComponent("New message from $name via GradeMate")
                                    val body = encodeURIComponent("From: $name ($email)\n\n$message")
                                    window.location.href =
                                        "mailto:lennycodes2000@gmail.com?subject=$subject&body=$body"
                                    name = ""
                                    email = ""
                                    message = ""
                                    statusIsError = false
                                    statusMessage =
                                        "Your email app is opening with the message ready. Just press send."
                                }
                            }
                        },
                        modifier = PrimaryButtonStyle
                            .toModifier()
                            .onMouseEnter { sendHovered = true }
                            .onMouseLeave { sendHovered = false }
                            .styleModifier {
                                property("display", "inline-flex")
                                property("align-items", "center")
                                property("justify-content", "center")
                                property("gap", "10px")
                                property("width", "100%")
                                property("height", "50px")
                                property("box-sizing", "border-box")
                                property("border-radius", "12px")
                                property("font-size", "15px")
                                property("font-weight", "600")
                                // Soft sheen over the brand colour
                                property(
                                    "background-image",
                                    "linear-gradient(135deg, rgba(255, 255, 255, 0.2), rgba(255, 255, 255, 0) 60%)"
                                )
                                property("transform", if (sendHovered) "translateY(-3px)" else "translateY(0)")
                                property(
                                    "box-shadow",
                                    if (sendHovered) "0 18px 34px -10px rgba(37, 99, 235, 0.5)"
                                    else "0 8px 20px -8px rgba(37, 99, 235, 0.4)"
                                )
                                property(
                                    "transition",
                                    "transform ${t(250)}ms $Ease, box-shadow ${t(250)}ms ease"
                                )
                            }
                    ) {
                        // The plane lifts off while the button is hovered
                        FaIcon(
                            name = "paper-plane",
                            style = IconCategory.SOLID,
                            modifier = Modifier
                                .fontSize(14.px)
                                .styleModifier {
                                    property(
                                        "transform",
                                        if (sendHovered) "translate(3px, -3px)" else "translate(0, 0)"
                                    )
                                    property("transition", "transform ${t(300)}ms $Ease")
                                }
                        )
                        Text("Send message")
                    }

                    statusMessage?.let { text ->
                        StatusBanner(
                            message = text,
                            isError = statusIsError,
                            onDismiss = { statusMessage = null }
                        )
                    }
                }
            }
        }
    }
}

/** Fades in under the button and clears itself after a few seconds. */
@Composable
private fun StatusBanner(
    message: String,
    isError: Boolean,
    onDismiss: () -> Unit
) {
    var shown by remember(message) { mutableStateOf(false) }
    val reduce = remember { prefersReducedMotion() }

    LaunchedEffect(message) {
        delay(20)
        shown = true
        delay(6000)
        onDismiss()
    }

    val tone = if (isError) "220, 38, 38" else "22, 163, 74"
    val ink = if (isError) "rgb(185, 28, 28)" else "rgb(21, 128, 61)"

    Div(
        attrs = Modifier
            .styleModifier {
                property("padding", "14px 18px")
                property("border-radius", "12px")
                property("background-color", "rgba($tone, 0.08)")
                property("border", "1px solid rgba($tone, 0.25)")
                property("color", ink)
                property("font-size", "14px")
                property("line-height", "1.6")
                property("opacity", if (shown) "1" else "0")
                property("transform", if (shown) "translateY(0)" else "translateY(8px)")
                property(
                    "transition",
                    "opacity ${if (reduce) 0 else 350}ms ease, transform ${if (reduce) 0 else 450}ms $Ease"
                )
            }
            .toAttrs { attr("role", if (isError) "alert" else "status") }
    ) {
        Text(if (isError) "❌ $message" else "✅ $message")
    }
}

@Composable
private fun ContactLink(
    href: String,
    iconName: String,
    iconCategory: IconCategory,
    label: String,
) {
    var hovered by remember { mutableStateOf(false) }
    val reduce = remember { prefersReducedMotion() }
    fun t(ms: Int) = if (reduce) 0 else ms

    Link(
        href,
        modifier = Modifier
            .fontSize(15.px)
            .color(GradeMateColors.TextPrimary)
            .onMouseEnter { hovered = true }
            .onMouseLeave { hovered = false }
            .styleModifier {
                property("display", "flex")
                property("align-items", "center")
                property("gap", "14px")
                property("text-decoration", "none")
                property("transform", if (hovered) "translateX(4px)" else "translateX(0)")
                property("transition", "transform ${t(300)}ms $Ease")
            }
    ) {
        // Circular icon chip: fills with the brand colour on hover
        Box(
            Modifier
                .size(40.px)
                .styleModifier {
                    property("display", "inline-flex")
                    property("align-items", "center")
                    property("justify-content", "center")
                    property("border-radius", "999px")
                    property(
                        "background-color",
                        if (hovered) GradeMateColors.Primary.toRgba() else GradeMateColors.Primary.toRgba(alpha = 0.10f)
                    )
                    property("color", if (hovered) "#ffffff" else GradeMateColors.Primary.toRgba())
                    property("flex-shrink", "0")
                    property(
                        "box-shadow",
                        if (hovered) "0 10px 20px -8px ${GradeMateColors.Primary.toRgba(alpha = 0.55f)}" else "none"
                    )
                    property(
                        "transition",
                        "background-color ${t(250)}ms ease, color ${t(250)}ms ease, box-shadow ${t(250)}ms ease"
                    )
                }
        ) {
            FaIcon(
                name = iconName,
                style = iconCategory,
                modifier = Modifier.fontSize(16.px)
            )
        }
        Text(label)
        // Arrow fades in on hover
        Span(
            attrs = Modifier
                .styleModifier {
                    property("opacity", if (hovered) "1" else "0")
                    property("transform", if (hovered) "translate(0, 0)" else "translate(-6px, 0)")
                    property("color", GradeMateColors.Primary.toRgba())
                    property("transition", "opacity ${t(250)}ms ease, transform ${t(300)}ms $Ease")
                }
                .toAttrs()
        ) {
            Text("→")
        }
    }
}

@Composable
private fun contactField(label: String, fieldId: String, field: @Composable () -> Unit) {
    Column(Modifier.fillMaxWidth().gap(8.px)) {
        Label(
            forId = fieldId,
            attrs = Modifier
                .fontSize(13.px)
                .fontWeight(FontWeight.SemiBold)
                .color(GradeMateColors.TextPrimary)
                .styleModifier { property("letter-spacing", "0.01em") }
                .toAttrs()
        ) {
            Text(label)
        }
        field()
    }
}